/** Real original TaskStore SQLite/AtomicFile and native facade; never a provider/model/device pass. */
@RunWith(RobolectricTestRunner.class)
@Config(sdk=35,manifest=Config.NONE,application=Application.class)
@SQLiteMode(SQLiteMode.Mode.NATIVE)
public final class DurableConversationHistoryNativeTest {
    private static final class Fixture implements AutoCloseable {
        final Context android=RuntimeEnvironment.getApplication();final File file=new File(android.getFilesDir(),"durable-"+UUID.randomUUID()+".json");
        final FeatureContext context=new FeatureContext(android,new SettingsStore(android),new SecretVault(android),event->{});
        TaskStore tasks;AssistantModule module;
        Fixture(byte[] legacy,boolean oldDatabase)throws Exception{
            android.deleteDatabase("pocket-world.db");if(oldDatabase)createOldDatabase(android);if(legacy!=null)Files.write(file.toPath(),legacy);
            tasks=new TaskStore(android);module=new AssistantModule(context,null,null,new AtomicFile(file),tasks);
        }
        ConversationRepository repo(){return tasks.conversationRepository();}
        SQLiteDatabase db()throws Exception{var f=TaskStore.class.getDeclaredField("db");f.setAccessible(true);return (SQLiteDatabase)f.get(tasks);}
        void seed(String cid,int count)throws Exception{repo().transaction(()->{repo().saveConversation(new JSONObject().put("conversationId",cid).put("title","实际原文 "+cid).put("updatedAt",1).put("messages",new JSONArray()));for(int i=0;i<count;i++)save(cid,"message-"+cid+"-"+i,1,"原始🙂 CAUSE-"+i,i%2==0?"user":"assistant");return null;});}
        void save(String cid,String id,long revision,String body,String role)throws Exception{repo().saveSource(ref(id,revision).toJson().put("conversationId",cid).put("role",role).put("deleted",false));repo().saveMessage(cid,new JSONObject().put("id",id).put("revision",revision).put("role",role).put("content",body).put("at",100));}
        JSONObject migrate()throws Exception{JSONObject review=module.reviewOriginalHistoryMigration();return module.activateOriginalHistoryMigration(review.getString("migrationTaskId"),review.getString("sourceSha256"),true);}
        JSONObject query(String cid,String text,int limit,String cursor)throws Exception{return module.queryRetainedHistory(module.openHistoryConversation(cid),new JSONObject().put("query",text).put("cursor",cursor).put("limit",limit).put("maxChars",16000),new RunControl());}
        void reopen()throws Exception{module.close();db().close();tasks=new TaskStore(android);module=new AssistantModule(context,null,null,new AtomicFile(file),tasks);}
        public void close()throws Exception{module.close();db().close();}
    }
    private static SourceRef ref(String id,long revision){return new SourceRef("message",id,revision,"owner","private");}
    private static MemoryBook.Scope scope()throws Exception{return MemoryBook.Scope.from(new JSONObject().put("ownerId","owner").put("spaceId","private"));}
    private static JSONObject nativeState(int count)throws Exception{
        JSONArray messages=new JSONArray(),sources=new JSONArray();for(int i=0;i<count;i++){String id="old-"+i,role=i%2==0?"user":"assistant";messages.put(new JSONObject().put("id",id).put("revision",i==0?9_000_000_000L:1L).put("role",role).put("content","旧真实原文🙂 "+i));sources.put(ref(id,i==0?9_000_000_000L:1L).toJson().put("conversationId","old-conversation").put("role",role).put("deleted",false));}
        return new JSONObject().put("version",2).put("conversations",new JSONArray().put(new JSONObject().put("conversationId","old-conversation").put("title","旧原件").put("messages",messages))).put("sourceStates",sources);
    }
    private static byte[] bytes(JSONObject value){return value.toString().getBytes(StandardCharsets.UTF_8);}
    private static void createOldDatabase(Context context){context.getDatabasePath("pocket-world.db").getParentFile().mkdirs();SQLiteDatabase db=SQLiteDatabase.openOrCreateDatabase(context.getDatabasePath("pocket-world.db"),null);try{db.execSQL("CREATE TABLE meta(key TEXT PRIMARY KEY,value TEXT NOT NULL)");db.execSQL("CREATE TABLE tasks(task_id TEXT PRIMARY KEY,document TEXT NOT NULL,updated_at INTEGER NOT NULL)");db.execSQL("CREATE TABLE runs(run_id TEXT PRIMARY KEY,task_id TEXT NOT NULL,epoch INTEGER NOT NULL,status TEXT NOT NULL,checkpoint TEXT NOT NULL,grant_json TEXT NOT NULL,created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL,UNIQUE(task_id,epoch))");db.execSQL("CREATE TABLE operations(operation_id TEXT PRIMARY KEY,task_id TEXT NOT NULL,run_id TEXT NOT NULL,tool TEXT NOT NULL,arguments TEXT NOT NULL,state TEXT NOT NULL,receipt TEXT,created_at INTEGER NOT NULL)");db.execSQL("CREATE INDEX operations_task ON operations(task_id,state)");db.execSQL("CREATE TABLE leases(resource_id TEXT PRIMARY KEY,run_id TEXT NOT NULL,epoch INTEGER NOT NULL,expires_at INTEGER NOT NULL)");db.setVersion(1);}finally{db.close();}}

    @Test public void freshInstallationWritesOnlyOriginalDatabaseAndReopensWithoutAtomicFile()throws Exception{
        try(Fixture f=new Fixture(null,false)){assertTrue(f.repo().active());assertFalse(f.file.exists());String testResource=DurableConversationHistoryNativeTest.class.getResource("/"+DurableConversationHistoryNativeTest.class.getName().replace('.','/')+".class").toString();String resourceRoot=testResource.substring(0,testResource.indexOf("dev/pocketengine/"));for(Class<?> actual:new Class<?>[]{TaskStore.class,AssistantModule.class,ConversationRepository.class,LegacyConversationImport.class,TaskMemoryNativeHost.class,FeatureHost.class})assertTrue(actual.getName()+" not from this fresh source output",actual.getResource("/"+actual.getName().replace('.','/')+".class").toString().startsWith(resourceRoot));f.seed("first",1);f.module.appendTaskResult("first","native-completed-task","真实存入DB的原答复");assertFalse(f.file.exists());f.reopen();assertEquals(2,f.module.readOriginalConversation("first","",80).getJSONArray("messages").length());assertFalse(f.file.exists());}
    }
    @Test public void uiTwentyAndEightyArePagesNotRetentionDeletes()throws Exception{
        try(Fixture f=new Fixture(null,false)){for(int i=0;i<23;i++)f.seed("conversation-"+i,1);JSONObject first=f.module.listOriginalConversations("",20),second=f.module.listOriginalConversations(first.getString("nextCursor"),20);assertEquals(20,first.getJSONArray("conversations").length());assertEquals(3,second.getJSONArray("conversations").length());assertFalse(first.getBoolean("retentionLimitApplied"));f.seed("long",1);for(int i=0;i<83;i++)f.module.appendTaskResult("long","native-task","答复 "+i);JSONObject window=f.module.readOriginalConversation("long","",80),older=f.module.readOriginalConversation("long",window.getJSONObject("messagePage").getString("nextCursor"),80);assertEquals(80,window.getJSONArray("messages").length());assertEquals(4,older.getJSONArray("messages").length());assertEquals("原始🙂 CAUSE-0",older.getJSONArray("messages").getJSONObject(0).getString("content"));assertFalse(f.module.resolveSource(scope(),"message-long-0").deleted);}
    }
    @Test public void schemaUpgradeCreatesNoContentAndDoesNotPretendMissingOldFileIsNewInstallation()throws Exception{
        try(Fixture f=new Fixture(null,true)){assertFalse(f.repo().active());assertEquals("future_retention_review_required",f.module.originalHistoryState().getString("status"));JSONObject review=f.module.reviewOriginalHistoryMigration();assertEquals("absent",review.getString("sourceCondition"));assertFalse(review.getBoolean("sourceSha256Known"));assertEquals("",review.getString("sourceSha256"));JSONObject result=f.module.activateOriginalHistoryMigration(review.getString("migrationTaskId"),"",true);assertTrue(f.repo().active());assertEquals(0,result.getInt("messages"));assertFalse(result.getBoolean("originalHistoryRecovered"));assertFalse(f.file.exists());}
        try(Fixture large=new Fixture(null,true)){try(java.io.RandomAccessFile file=new java.io.RandomAccessFile(large.file,"rw")){file.setLength((long)LegacyConversationImport.MAX_SOURCE_BYTES+1);}large.reopen();assertEquals("legacy_source_read_limited",large.module.originalHistoryState().getString("status"));assertFalse(large.repo().active());assertThrows(Exception.class,large.module::reviewOriginalHistoryMigration);assertEquals((long)LegacyConversationImport.MAX_SOURCE_BYTES+1,large.file.length());}
    }
    @Test public void absenceCasRejectsAFileAppearingAfterExplicitReview()throws Exception{
        try(Fixture f=new Fixture(null,true)){JSONObject review=f.module.reviewOriginalHistoryMigration();byte[] arrived=bytes(nativeState(1));Files.write(f.file.toPath(),arrived);assertThrows(Exception.class,()->f.module.activateOriginalHistoryMigration(review.getString("migrationTaskId"),"",true));assertFalse(f.repo().active());assertArrayEquals(arrived,Files.readAllBytes(f.file.toPath()));}
    }
    @Test public void sourceShaReviewIsRequiredAndStagingIsNotAuthority()throws Exception{
        byte[] original=bytes(nativeState(2));try(Fixture f=new Fixture(original,true)){assertFalse(f.repo().active());assertArrayEquals(original,Files.readAllBytes(f.file.toPath()));JSONObject review=f.module.reviewOriginalHistoryMigration();assertEquals(ConversationRepository.shaBytes(original),review.getString("sourceSha256"));JSONObject counts=f.tasks.stageConversationHistory(review,new JSONObject(new String(original,StandardCharsets.UTF_8)),()->null);assertFalse(f.repo().resolveMetadata("old-0").databaseAuthority);assertFalse(f.repo().active());assertThrows(SecurityException.class,()->f.tasks.activateConversationHistory(review,new JSONObject(counts.toString()).put("messages",99),()->review.getString("sourceSha256")));assertFalse(f.repo().active());assertTrue(f.file.exists());f.tasks.requestCancel(review.getString("migrationTaskId"),review.getString("migrationTaskId"));assertThrows(Exception.class,()->f.module.activateOriginalHistoryMigration(review.getString("migrationTaskId"),review.getString("sourceSha256"),true));assertFalse(f.repo().active());assertEquals("cancelled",f.tasks.get(review.getString("migrationTaskId"),false).getString("status"));assertArrayEquals(original,Files.readAllBytes(f.file.toPath()));}
    }
    @Test public void exactNativeMetadataTimeUnknownAttachmentAndAckSurviveCutover()throws Exception{
        JSONObject state=nativeState(2),message=state.getJSONArray("conversations").getJSONObject(0).getJSONArray("messages").getJSONObject(0),source=state.getJSONArray("sourceStates").getJSONObject(0);String client=UUID.randomUUID().toString();JSONObject attachment=new JSONObject().put("id","native-attachment-ref").put("version",4).put("sha256","a".repeat(64));message.put("attachments",new JSONArray().put(attachment)).put("memoryReference",new JSONObject().put("receiptId","native-old-receipt"));source.put("clientMessageId",client).put("requestFingerprint","native-fingerprint").put("submission",new JSONObject().put("accepted",true).put("taskId","original-task").put("runId","original-run").put("inputId","original-input").put("status","consumed"));
        try(Fixture f=new Fixture(bytes(state),true)){JSONObject receipt=f.migrate();assertFalse(receipt.getBoolean("legacyCleanupPending"));assertFalse(f.file.exists());JSONObject restored=f.module.readOriginalConversation("old-conversation","",80).getJSONArray("messages").getJSONObject(0);assertEquals(9_000_000_000L,restored.getLong("revision"));assertFalse(restored.has("at"));assertEquals(attachment.toString(),restored.getJSONArray("attachments").getJSONObject(0).toString());assertEquals("native-old-receipt",restored.getJSONObject("memoryReference").getString("receiptId"));assertEquals("original-input",f.module.handle("getSubmission",new JSONObject().put("clientMessageId",client)).getString("inputId"));f.reopen();assertEquals(9_000_000_000L,f.module.resolveSource(scope(),"old-0").ref.revision);}
    }
    @Test public void changedLegacyBytesCannotActivateOrEraseOriginal()throws Exception{
        try(Fixture f=new Fixture(bytes(nativeState(1)),true)){JSONObject review=f.module.reviewOriginalHistoryMigration();byte[] changed=bytes(nativeState(2));Files.write(f.file.toPath(),changed);assertThrows(Exception.class,()->f.module.activateOriginalHistoryMigration(review.getString("migrationTaskId"),review.getString("sourceSha256"),true));assertFalse(f.repo().active());assertArrayEquals(changed,Files.readAllBytes(f.file.toPath()));}
    }
    @Test public void activationFailureRollsBackAuthorityAndOriginalOperationTogether()throws Exception{
        try(Fixture f=new Fixture(bytes(nativeState(1)),true)){f.db().execSQL("CREATE TRIGGER fixture_abort_history BEFORE INSERT ON meta WHEN NEW.key='assistant_history_generation' BEGIN SELECT RAISE(ABORT,'fixture activation failure');END");assertThrows(Exception.class,f::migrate);assertFalse(f.repo().active());try(Cursor row=f.db().rawQuery("SELECT count(*) FROM meta WHERE key='assistant_history_authority'",null)){row.moveToFirst();assertEquals(0,row.getInt(0));}assertTrue(f.file.exists());assertEquals("failed",f.tasks.conversationHistoryMigration().getJSONObject("receipt").getString("status"));}
    }
    @Test public void recoveredUnknownStageNeedsNewExplicitReviewAndNeverAutomaticReplay()throws Exception{
        byte[] original=bytes(nativeState(1));try(Fixture f=new Fixture(original,true)){JSONObject first=f.module.reviewOriginalHistoryMigration();f.tasks.stageConversationHistory(first,new JSONObject(new String(original,StandardCharsets.UTF_8)),()->null);f.reopen();assertFalse(f.repo().active());assertEquals("unknown",f.tasks.conversationHistoryMigration().getString("operationState"));JSONObject next=f.module.reviewOriginalHistoryMigration();assertNotEquals(first.getString("migrationTaskId"),next.getString("migrationTaskId"));try(Cursor rows=f.db().rawQuery("SELECT count(*) FROM assistant_messages WHERE generation=?",new String[]{first.getString("migrationTaskId")})){rows.moveToFirst();assertEquals(0,rows.getInt(0));}assertEquals("cancelled",f.tasks.get(first.getString("migrationTaskId"),false).getString("status"));}
    }
    @Test public void longHistoryDeleteBeyondWindowAndWholeConversationNeverReviveBodies()throws Exception{
        try(Fixture f=new Fixture(null,false)){f.seed("long",85);f.module.handle("deleteMessage",new JSONObject().put("conversationId","long").put("messageId","message-long-0").put("revision",1));SourceRef.State deleted=f.module.resolveSource(scope(),"message-long-0");assertTrue(deleted.deleted);assertEquals(2,deleted.ref.revision);assertEquals(0,f.query("long","CAUSE-0",20,"").getJSONArray("entries").length());f.module.handle("delete",new JSONObject().put("conversationId","long"));assertTrue(f.module.resolveSource(scope(),"message-long-84").deleted);try(Cursor row=f.db().rawQuery("SELECT count(*) FROM assistant_messages WHERE body IS NOT NULL",null)){row.moveToFirst();assertEquals(0,row.getInt(0));}assertThrows(Exception.class,()->f.module.readOriginalConversation("long","",80));}
    }
    @Test public void forgettingRetiresAutomaticHistoryButKeepsOwnerOriginalUtterance()throws Exception{
        try(Fixture f=new Fixture(null,false)){f.seed("c",2);SourceRef original=ref("message-c-0",1);ConversationHistory.Gate gate=f.module.openHistoryConversation("c");JSONObject removed=new JSONObject().put("sourceRefs",new JSONArray().put(original.toJson()));assertEquals(2,f.module.retireMemoryContexts(new JSONArray().put(removed),"owner_forget"));assertEquals(0,f.module.retireMemoryContexts(new JSONArray().put(removed),"owner_forget"));assertFalse(f.module.resolveSource(scope(),original.sourceId).deleted);JSONObject rejected=f.module.readHistoryMessage(gate,original,0,100,new RunControl());assertEquals("retired",rejected.getString("status"));assertFalse(rejected.has("body"));assertEquals("原始🙂 CAUSE-0",f.module.readOriginalConversation("c","",80).getJSONArray("messages").getJSONObject(0).getString("content"));assertEquals(0,f.query("c","CAUSE",20,"").getJSONArray("entries").length());}
    }
    @Test public void normalAppendKeepsSourceAndOldCursorButExcludesNewTailFromItsWatermark()throws Exception{
        try(Fixture f=new Fixture(null,false)){f.seed("c",3);ConversationHistory.Gate gate=f.module.openHistoryConversation("c");JSONObject first=f.query("c","",1,"");f.module.appendTaskResult("c","native-task","后来新增尾部");assertTrue(gate.current());assertEquals("current",f.module.readHistoryMessage(gate,ref("message-c-0",1),0,100,new RunControl()).getString("status"));JSONObject next=f.query("c","",20,first.getString("nextCursor"));assertEquals(2,next.getJSONArray("entries").length());assertFalse(next.toString().contains("后来新增尾部"));assertEquals(3,next.getJSONObject("pageCoverage").getLong("upperSequence"));}
    }
    @Test public void oversizedBodyIsPreflightedAndDoesNotHideFollowingUiPage()throws Exception{
        try(Fixture f=new Fixture(null,false)){f.seed("c",1);f.repo().transaction(()->{f.save("c","large",1,"字".repeat(400_000),"user");return null;});JSONObject page=f.module.readOriginalConversation("c","",1);assertEquals(0,page.getJSONArray("messages").length());assertTrue(page.getJSONObject("messagePage").getBoolean("hasMore"));JSONObject older=f.module.readOriginalConversation("c",page.getJSONObject("messagePage").getString("nextCursor"),1);assertEquals(1,older.getJSONArray("messages").length());JSONObject result=f.query("c","",20,"");assertEquals(1,result.getJSONArray("entries").length());assertEquals("read_limited",result.getJSONArray("gaps").getJSONObject(0).getString("status"));assertFalse(result.toString().contains("字字字字字"));}
    }
    @Test public void metadataReadDoesNotAcquireTaskMonitorAndCommitDeletionIsImmediatelyVisible()throws Exception{
        try(Fixture f=new Fixture(null,false)){f.seed("c",1);ExecutorService executor=Executors.newSingleThreadExecutor();try{synchronized(f.tasks){SourceRef.State state=executor.submit(()->f.module.resolveSource(scope(),"message-c-0")).get(2,TimeUnit.SECONDS);assertFalse(state.deleted);}f.module.handle("deleteMessage",new JSONObject().put("conversationId","c").put("messageId","message-c-0").put("revision",1));assertTrue(executor.submit(()->f.module.resolveSource(scope(),"message-c-0")).get(2,TimeUnit.SECONDS).deleted);}finally{executor.shutdownNow();}}
    }
    @Test public void cancelledMetadataWaitFailsClosedAndReleasesBookForExistingWriter()throws Exception{
        try(Fixture f=new Fixture(null,false)){f.seed("c",1);Object book=new Object();CountDownLatch bookHeld=new CountDownLatch(1),writing=new CountDownLatch(1);ExecutorService pool=Executors.newFixedThreadPool(2,r->{Thread t=new Thread(r,"fixture-history-lock");t.setDaemon(true);return t;});
            try{Future<Boolean> read=pool.submit(()->{synchronized(book){bookHeld.countDown();assertTrue(writing.await(2,TimeUnit.SECONDS));long start=System.nanoTime();try{f.module.resolveSource(scope(),"message-c-0");return false;}catch(Exception cancelled){assertTrue("best effort native wait did not release in fixture",System.nanoTime()-start<3_000_000_000L);return true;}}});Future<?> writer=pool.submit(()->{try{assertTrue(bookHeld.await(2,TimeUnit.SECONDS));synchronized(f.tasks){SQLiteDatabase db=f.db();db.beginTransaction();try{writing.countDown();synchronized(book){db.setTransactionSuccessful();}}finally{db.endTransaction();}}}catch(Exception bad){throw new RuntimeException(bad);}});assertTrue(read.get(5,TimeUnit.SECONDS));writer.get(5,TimeUnit.SECONDS);}finally{pool.shutdownNow();}
        }
    }
    @Test public void unversionedOriginalBytesRemainUntouchedAndUnknownRecordsUseOnlyInternalLocators()throws Exception{
        byte[] raw=(" [ {\"conversationId\":\"old-array\",\"title\":\"旧原样\",\"messages\":[ {\"role\":\"user\",\"content\":\"旧未知🙂，{不是边界}\\\"\"}, {\"role\":\"assistant\",\"content\":\"旧答复\"} ]} ] ").getBytes(StandardCharsets.UTF_8);
        try(Fixture f=new Fixture(raw,true)){assertArrayEquals(raw,Files.readAllBytes(f.file.toPath()));assertNull(f.module.resolveSource(scope(),"import-message:"+ConversationRepository.shaBytes(raw)+":0:0"));JSONObject review=f.module.reviewOriginalHistoryMigration();assertEquals(2,review.getInt("retainedUnverifiedRecords"));f.module.activateOriginalHistoryMigration(review.getString("migrationTaskId"),review.getString("sourceSha256"),true);JSONArray messages=f.module.readOriginalConversation("old-array","",80).getJSONArray("messages");JSONObject first=messages.getJSONObject(0);assertTrue(first.getBoolean("importAssignedIdentity"));assertEquals(1,first.getLong("recordVersion"));assertTrue(first.isNull("revision"));assertTrue(first.isNull("historicalRevision"));assertTrue(first.isNull("at"));assertFalse(first.getBoolean("formalSourceRefAvailable"));assertNull(f.module.resolveSource(scope(),first.getString("recordId")));JSONObject byteRef=first.getJSONObject("originalByteReference");byte[] fragment=Arrays.copyOfRange(raw,byteRef.getInt("offset"),byteRef.getInt("offset")+byteRef.getInt("length"));assertEquals(first.getString("content"),new JSONObject(new String(fragment,StandardCharsets.UTF_8)).getString("content"));assertEquals(ConversationRepository.shaBytes(fragment),byteRef.getString("fragmentSha256"));f.module.appendTaskResult("old-array","native-new-task","新的原生答复");assertEquals(3,f.module.readOriginalConversation("old-array","",80).getJSONArray("messages").length());assertEquals(1,f.query("old-array","",20,"").getJSONArray("entries").length());}
    }
    @Test public void importedDeletionErasesOwnedOriginalFragmentWithoutChangingOtherByteReference()throws Exception{
        byte[] raw="[{\"conversationId\":\"old\",\"messages\":[{\"role\":\"user\",\"content\":\"消除这个旧原件\"},{\"role\":\"assistant\",\"content\":\"保留另一段原样\"}]}]".getBytes(StandardCharsets.UTF_8);
        try(Fixture f=new Fixture(raw,true)){f.migrate();JSONArray before=f.module.readOriginalConversation("old","",80).getJSONArray("messages");JSONObject first=before.getJSONObject(0),second=before.getJSONObject(1);f.module.deleteOriginalImportedRecord("old",first.getString("recordId"),1);assertNull(f.repo().importedMessage("old",first.getString("recordId")));assertEquals(second.getJSONObject("originalByteReference").toString(),f.repo().read(()->f.repo().importedMessage("old",second.getString("recordId"))).getJSONObject("originalByteReference").toString());try(Cursor erased=f.db().rawQuery("SELECT data FROM assistant_import_fragments WHERE record_id=?",new String[]{first.getString("recordId")})){assertTrue(erased.moveToFirst());assertTrue(erased.isNull(0));}f.module.handle("delete",new JSONObject().put("conversationId","old"));try(Cursor erased=f.db().rawQuery("SELECT count(*) FROM assistant_import_fragments WHERE conversation_id='old' AND data IS NOT NULL",null)){erased.moveToFirst();assertEquals(0,erased.getInt(0));}}
    }
    private static final class CleanupFailure extends AtomicFile {boolean fail=true;CleanupFailure(File file){super(file);}@Override public void delete(){if(fail)throw new IllegalStateException("fixture legacy cleanup failure");super.delete();}}
    @Test public void cleanupFailureLeavesCommittedAuthorityAndNeverFallsBackToChangedOldFile()throws Exception{
        try(Fixture f=new Fixture(bytes(nativeState(1)),true)){f.module.close();CleanupFailure legacy=new CleanupFailure(f.file);f.module=new AssistantModule(f.context,null,null,legacy,f.tasks);assertThrows(Exception.class,f::migrate);assertTrue(f.repo().active());assertTrue(f.repo().authority().getBoolean("legacyCleanupPending"));byte[] foreign="changed non-authoritative old bytes".getBytes(StandardCharsets.UTF_8);Files.write(f.file.toPath(),foreign);f.reopen();assertEquals("旧真实原文🙂 0",f.module.readOriginalConversation("old-conversation","",80).getJSONArray("messages").getJSONObject(0).getString("content"));String sha=f.repo().authority().getString("legacySourceSha256");assertTrue(f.module.cleanupOriginalHistoryMigration(sha).getBoolean("legacyCleanupPending"));assertArrayEquals(foreign,Files.readAllBytes(f.file.toPath()));}
    }
    @Test public void sourceAndContainerTombstonesKeepKnownReasonsAndDoNotInventOldUnknownReason()throws Exception{
        JSONObject legacy=nativeState(1);JSONArray states=legacy.getJSONArray("sourceStates");states.put(ref("known-delete",2).toJson().put("conversationId","old-conversation").put("deleted",true).put("unavailableReason","user_message_delete"));states.put(ref("old-unknown",2).toJson().put("conversationId","lost-container").put("deleted",true));
        try(Fixture f=new Fixture(bytes(legacy),true)){f.migrate();assertEquals("user_message_delete",f.repo().read(()->f.repo().source("known-delete")).getString("unavailableReason"));assertEquals("unknown",f.repo().read(()->f.repo().source("old-unknown")).getString("unavailableReason"));f.db().execSQL("UPDATE assistant_conversations SET deleted=1,delete_reason='user_conversation_delete' WHERE conversation_id='old-conversation'");assertTrue(f.module.resolveSource(scope(),"old-0").deleted);assertNull(f.module.resolveSource(MemoryBook.Scope.from(new JSONObject().put("ownerId","other").put("spaceId","private")),"old-0"));}
    }
    @Test public void realNativeCallerAcceptsOnlyOwnerFieldsAndMigrationIsNotAnEngineCommand()throws Exception{
        try(Fixture f=new Fixture(bytes(nativeState(1)),true);FeatureHost host=new FeatureHost(event->{},f.tasks,()->false)){host.register(f.module);MemorySourceBridge bridge=new MemorySourceBridge(host,f.tasks);bridge.bindAssistant(f.module);TaskMemoryNativeHost nativeHost=new TaskMemoryNativeHost(host,f.tasks,bridge);assertThrows(IllegalArgumentException.class,()->f.module.handle("activateOriginalConversationHistoryMigration",new JSONObject()));assertThrows(SecurityException.class,()->nativeHost.handle("listOriginalConversations",new JSONObject().put("limit",20).put("ownerId","other")));JSONObject review=nativeHost.handle("reviewOriginalConversationHistoryMigration",new JSONObject());assertThrows(SecurityException.class,()->nativeHost.handle("activateOriginalConversationHistoryMigration",new JSONObject().put("reviewTaskId",review.getString("migrationTaskId")).put("sourceSha256",review.getString("sourceSha256")).put("confirmOriginalScope","true")));nativeHost.handle("activateOriginalConversationHistoryMigration",new JSONObject().put("reviewTaskId",review.getString("migrationTaskId")).put("sourceSha256",review.getString("sourceSha256")).put("confirmOriginalScope",true));assertEquals(1,nativeHost.handle("listOriginalConversations",new JSONObject().put("limit",20)).getJSONArray("conversations").length());}
    }
}
